            "correctKey": "Б",
            "answerText": "Ковалентний зв’язок у звичайному описі утворює спільна електронна пара між зв’язаними атомами. Водневий — взаємодія атомаH, ковалентно зв’язаного з електронегативним атомом, із відповідним електронним центром, наприклад неподіленою пароюO іншої молекули. Він слабший за типовий ковалентний і може бути міжмолекулярним або внутрішньомолекулярним.",
            "number": 9
