            "answerText": "Дано10л рідкого пентану,ρ=0,626г/см³, а не10л газу. Vрідини=10000см³,m=6260г;M(C₅H₁₂)=72г/моль,n=6260/72≈86,944моль. C₅H₁₂+8O₂→5CO₂+6H₂O, отжеnO₂≈695,556моль. За н.у.VO₂=n·22,4≈15580,44л. Для20об.%O₂ Vпов=VO₂/0,20≈77902,22л≈77,9м³. Розрахунок припускає повне горіння й достатній доступ кисню; це теоретична кількість, не режим практичного спалювання.",
