            "answerText": "Для одного моля пропану: C₃H₈+5O₂→3CO₂+4H₂O; ΔH=−2200кДж за умовами задачі. Негативний знак означає виділення теплоти. Значення прив’язане до кількості речовини, коефіцієнтів і фазових умов, а не є універсальним для будь-якого запису з довільними коефіцієнтами.",
