            "answerText": "Маса початкового1мольетену28г збереглася:0,2·28+0,8·26+0,8·2=28г. Загальнеn=1,8моль, середняM=28/1,8≈15,56г/моль. Число молів більше через відщепленняH₂; маса не зникла.",
