            "answerText": "Вихідні0,2мольC₂H₂ частково тримеризуються:3C₂H₂→C₆H₆. У надлишку бромної води залишковийетин приєднує2Br₂, а бензен за цих умов не реагує. nBr₂=16/160=0,1моль; залишокетину0,05моль. На бензен перетворилось0,2−0,05=0,15мольетину, отжеnбензену0,05моль. У газовій/паровій суміші за однакових умовVетину:Vбензену=1:1. За охолодження з конденсацією бензену співвідношення газових об’ємів потребувало б іншого опису.",
