            "correctKey": "Г",
            "answerText": "З переліку спирти:C₂H₅OH,CH₃OH,C₂H₄(OH)₂,C₃H₅(OH)₃. Перші дваодноатомні, наступнідво- йтриатомний. C₂H₅OC₂H₅ — етер безOH, галогенопохідні не містятьOH, C₂H₄ — вуглеводень. Число атомівO саме по собі недостатнє для класифікації.",
