            "assessmentAspect": "Чим насичений одноатомний спирт відрізняється від відповідного алкану за будовою?",
            "questionHtml": "<p>Чим насичений одноатомний спирт відрізняється від відповідного алкану за будовою?</p>",
            "options": [
              {
                "key": "А",
                "text": "Молекула містить лише C і H",
                "textHtml": "<p>Молекула містить лише C і H</p>"
              },
              {
                "key": "Б",
                "text": "Один C замінений на Na",
                "textHtml": "<p>Один C замінений на Na</p>"
              },
              {
                "key": "В",
                "text": "Один H алкану формально замінений на OH",
                "textHtml": "<p>Один H алкану формально замінений на OH</p>"
              },
              {
                "key": "Г",
                "text": "Усі зв’язки C–C обов’язково подвійні",
                "textHtml": "<p>Усі зв’язки C–C обов’язково подвійні</p>"
              }
            ],
            "correctKey": "В",
            "answerText": "Вуглеводні складаються лише з C і H. Насичений одноатомний спирт R–OH містить алкільний залишок і одну OH-групу; формально це продукт заміни одного H алкану на OH. Зв’язки C–O та O–H полярні, O–H полярніший; між молекулами спиртів можливі водневі зв’язки.",
