            "correctKey": "А",
            "answerText": "Властивості визначають OH-група, розмір і будова вуглеводневого залишку. Міжмолекулярні водневі зв’язки підвищують температуру кипіння порівняно з близькими алканами. Зі зростанням неполярної частини в гомологічному ряду розчинність у воді загалом зменшується; розгалуження також змінює властивості, тому правило лише за числом C не універсальне для всіх ізомерів.",
