            "answerText": "C₂H₅COOCH₃ + H₂O ⇄ C₂H₅COOH + CH₃OH, кислотний каталіз, нагрівання. Продукти — пропанова кислота і метанол. У лужному середовищі: C₂H₅COOCH₃ + NaOH → C₂H₅COONa + CH₃OH; там утворюється сіль, а не вільна кислота.",
