            "assessmentAspect": "Яка початкова маса метанолу, якщо утворилось20,4 г метилбутаноату, а прореагувало80% спирту?",
            "questionHtml": "<p>Яка початкова маса метанолу, якщо утворилось20,4 г метилбутаноату, а прореагувало80% спирту?</p>",
