            "correctKey": "А",
            "answerText": "Історична назва «вуглеводи» пов’язана зі складом багатьох представників, який формально записують Cₙ(H₂O)ₘ: глюкоза C₆(H₂O)₆, сахароза C₁₂(H₂O)₁₁, крохмаль і целюлоза [C₆(H₂O)₅]ₙ. Це не суміші вуглецю з водою і не кристалогідрати. Підручник пов’язує назву також з обвугленням при нагріванні; реальний термоліз може давати й інші продукти. Є вуглеводи, склад яких не відповідає цьому співвідношенню, і не кожна сполука з ним є вуглеводом.",
            "number": 1
