            "correctKey": "В",
            "answerText": "Альдегідну функцію відкритої форми виявляють «срібним дзеркалом» при нагріванні з амоніачним реактивом Ag(I) або появою червоного Cu₂O при нагріванні з Cu(OH)₂ у лужному середовищі. У воді переважають циклічні форми, але вони рівноважно переходять у відкриту HOCH₂–(CHOH)₄–CHO, яка окиснюється. Ця проба не означає, що всі молекули глюкози постійно мають відкриту CHO-групу.",
