            "type": "single",
            "topic": "§ 24. Дисахариди. Сахароза",
            "assessmentAspect": "Які продукти та відповідний зміст має крок178 «сахароза → глюкоза»?",
            "questionHtml": "<p>Які продукти та відповідний зміст має крок178 «сахароза → глюкоза»?</p>",
