            "answerText": "Крок178 «сахароза → глюкоза»: C₁₂H₂₂O₁₁ + H₂O → C₆H₁₂O₆(глюкоза) + C₆H₁₂O₆(фруктоза). Гідроліз, відповідний фермент або нагрівання з розбавленою сильною кислотою. Другий продукт — фруктозу — не можна пропускати в рівнянні.",
