            "correctKey": "Г",
            "answerText": "Для70%-го розчину на100 г води припадає70/30·100≈233,3 г сахарози. На графіку мал.60 (PDF143) при60 °C розчинність приблизно290 г/100 г води. Оскільки233,3<290, розчин ненасичений. Порівнюємо однакові величини: грами цукру на100 г води, а не безпосередньо70% з290.",
