            "correctKey": "В",
            "answerText": "Для83%-го розчину:83/17·100≈488,2 г сахарози на100 г води. Графік мал.60 при100 °C дає близько490–500 г/100 г води (приблизно83% у насиченому розчині). У межах точності графіка розчин вважаємо практично насиченим. Робити категоричний висновок за різницею кількох грамів із цього схематичного графіка не можна; за точним значенням500 г це було б83,33%, і83% трохи нижче межі.",
