            "correctKey": "В",
            "answerText": "Нехай x г чистого цукру, тоді200−x г10%-го розчину. Баланс:x+0,10(200−x)=200·0,20=40;0,90x=20,x≈22,222 г. Розчину200−x≈177,778 г. Перевірка22,222+17,778=40 г сахарози в200 г суміші.",
