            "correctKey": "Г",
            "answerText": "Гідроліз342 г сахарози дає180 г глюкози і180 г фруктози, додаткові18 г надходять із води. Нехай початкова маса сахарози m, її прореагована частка α; mглюкози=αm·180/342. За умовою цеm/2, тому α=(1/2)·342/180=0,95=95%. Не50%, бо маси сахарози та утвореної саме глюкози не рівні при повному гідролізі.",
