            "assessmentAspect": "Скільки етанолу добудуть з1 т картоплі з25% крохмалю за загальних втрат20%?",
            "questionHtml": "<p>Скільки етанолу добудуть з1 т картоплі з25% крохмалю за загальних втрат20%?</p>",
