            "correctKey": "Б",
            "answerText": "За припущенням, що домішки не містять N, уся маса Нітрогену припадає на метиламін. У чистому аміні wN=14/31. Частка метиламіну0,40/(14/31)=0,885714; домішок1−0,885714≈0,114286=11,43%. Якщо домішки теж містять N, одного вимірювання40% недостатньо; це обов’язкова умова розрахунку.",
