            "answerText": "M≈2,52·29=73,08≈73 г/моль. Для насиченого ациклічного первинного моноаміну CₙH₂ₙ₊₃N:14n+17=73,n=4. Формула C₄H₉NH₂=C₄H₁₁N; ця інформація не визначає єдиного положення NH₂ або скелета.",
