            "answerText": "14/(14n+17)=0,311; M≈45,016,n≈2. Формула C₂H₅NH₂, етиламін у розглянутому первинному ряду. Якщо розглядати також вторинні аміни, C₂H₇N має ізомер диметиламін; клас тут уточнено.",
