            "assessmentAspect": "Який амін дає при повному згорянні0,30 моль сухих CO₂+N₂, з яких після лугу залишається0,10 моль N₂?",
            "questionHtml": "<p>Який амін дає при повному згорянні0,30 моль сухих CO₂+N₂, з яких після лугу залишається0,10 моль N₂?</p>",
