            "topic": "§ 27. Анілін",
            "assessmentAspect": "Яка початкова маса нітробензену потрібна для200 кг аніліну при перетворенні95% вихідної сполуки?",
            "questionHtml": "<p>Яка початкова маса нітробензену потрібна для200 кг аніліну при перетворенні95% вихідної сполуки?</p>",
