            "correctKey": "Б",
            "answerText": "C₆H₅NO₂+3H₂→C₆H₅NH₂+2H₂O (t250–350 °C, каталізатор). Mнітробензену123, Mаніліну93 г/моль. Прореагована маса нітробензену200·123/93≈264,516 кг. Початкова маса264,516/0,95≈278,438 кг≈278,4 кг. Передбачається, що прореаговані95% перетворились на анілін без інших втрат.",
