            "assessmentAspect": "Яке атомне співвідношення C:N випливає з1,3 моль сухих CO₂+N₂ і0,1 моль N₂ після поглинанняCO₂?",
            "questionHtml": "<p>Яке атомне співвідношення C:N випливає з1,3 моль сухих CO₂+N₂ і0,1 моль N₂ після поглинанняCO₂?</p>",
