            "correctKey": "Б",
            "answerText": "γ-Аміномасляна кислота H₂NCH₂CH₂CH₂COOH=C₄H₉NO₂. M=48+9+14+32=103 г/моль. wC=48/103≈0,46602=46,6%. γ відповідає C4, а не C3, оскільки карбоксильнийC до грецького відліку не входить.",
