            "correctKey": "Г",
            "answerText": "За ρводи≈1 г/мл100 мл води мають100 г. Нехай m г гліцину: m/(m+100)=0,167;0,833m=16,7; m≈20,048 г≈20,0 г. Різниця від20 зумовлена округленою часткою16,7%;20/120≈16,667% округлюється так само.",
