            "correctKey": "А",
            "answerText": "У білку є йоногенні кислотні й основні групи: кінцеві COOH/NH₂ та відповідні бічні групи залишків. Вони можуть віддавати чи приєднувати H⁺, тому білок реагує з лугами й кислотами та має заряд, залежний від pH. Амфотерність не означає, що всі пептидні групи є вільними COOH і NH₂.",
