            "correctKey": "Б",
            "answerText": "При молочнокислому бродінні утворюється кислота, pH падає. Поблизу ізоелектричної області казеїну близькоpH4,6 зменшується електростатична стабілізація казеїнових частинок, вони агрегують і дають згусток. PDF173 узагальнює це як осадження білків; називати будь-яке таке осадження простим руйнуванням глобули надто грубо. Уточнення перевірено зовнішнім фаховим джерелом University of Guelph, Milk Proteins, розділpH: https://books.lib.uoguelph.ca/dairyscienceandtechnologyebook/chapter/milk-proteins-caseins-casein-micelles-whey-proteins-enzymes/ .",
