            "answerText": "Типовий полімерний зразок містить ланцюги різної довжини й маси, тому характеризується середньою молекулярною масою. У шкільній моделі Mr≈n̄·Mrланки, де n̄ — середній ступінь полімеризації; внеском кінцевих груп нехтують. Це не означає однакової маси всіх ланцюгів; існують різні способи усереднення, а в задачі використано задану просту модель.",
