            "externalId": "chemistry-popel-2018:31.04.b:08",
            "sourceCardId": "31.04.b",
            "sourceReference": "ДЖЕРЕЛО 31.04.b; TXT 3.txt, рядок 150; друковані/PDF 183, 184, 185.",
