            "type": "single",
            "topic": "§ 31. Добування високомолекулярних сполук",
            "assessmentAspect": "Скільки молекул води виділяється при утворенні одного лінійного ланцюга з n молекул гліцину?",
            "questionHtml": "<p>Скільки молекул води виділяється при утворенні одного лінійного ланцюга з n молекул гліцину?</p>",
