            "topic": "§ 31. Добування високомолекулярних сполук",
            "assessmentAspect": "Скільки пептидних груп утворилось, якщо при відповідній конденсації виділилось3 моль води?",
            "questionHtml": "<p>Скільки пептидних груп утворилось, якщо при відповідній конденсації виділилось3 моль води?</p>",
