            "correctKey": "Б",
            "answerText": "Переваги багатьох пластмас: мала густина, формованість, електроізоляційність, стійкість до певних середовищ, можливість підібрати властивості добавками. Це не абсолютна стійкість до всіх речовин і температур; вимоги залежать від застосування.",
            "number": 8
