            "answerText": "Повідомлення. Органічним(акриловим) склом зазвичай називають поліметилметакрилат, PMMA, прозорий термопласт. Повторювана ланка[–CH₂–C(CH₃)(COOCH₃)–]ₙ походить від метилметакрилату. Використання:прозорі панелі й скління, вивіски, світлорозсіювачі та світловоди; спеціальні марки — авіаційне скління. Конкретна придатність залежить від марки й вимог. Зовнішня перевірка на вимогу239: виробник PLEXIGLAS, https://www.plexiglas.de/en/service/product-info/what-is-plexiglas і https://www.plexiglas.de/en/products/plexiglas/solid-sheets-blocks . Не ототожнюємо PMMA з кожним прозорим пластиком.",
