            "correctKey": "Г",
            "answerText": "Каучуки — еластомерні полімери: у відповідному температурному діапазоні після зняття навантаження значною мірою відновлюють форму. Натуральний каучук переважноцис-1,4-поліізопрен; не розчиняється у воді, може розчинятися в певних органічних розчинниках, повільно окиснюється. Властивості різних синтетичних каучуків і їх температурні межі різняться;−50 °C не є універсальною межею для кожного виду.",
