            "correctKey": "А",
            "answerText": "Фредерік Волтон розробив лінолеум на основі окисненої лляної олії й запатентував відповідне покриття1863 року. Назву пов’язано з латинськимиlinum(льон) іoleum(олія). Історичний натуральний лінолеум не тотожний усім сучасним підлоговим покриттям із ПВХ, які в побуті також називають«лінолеумом». Джерело244в: Forbo, The Heritage of Marmoleum https://www.forbo.com/flooring/en-uk/inspiration-references/making-spaces-into-places-blog/the-heritage-of-marmoleum/p85so5 .",
