            "correctKey": "В",
            "answerText": "Для морських суден доцільні стійкість до води й солей,вологи та біообростання,механічна довговічність;для конкретних деталей важливі також УФ-стійкість,пожежні властивості,маса й ремонтопридатність. Застосовують матеріали,перевірені для відповідної функції. Це пропозиція до відкритого питання,не універсальний числовий стандарт для кожного полімеру.",
