            "answerText": "Сценарна відповідь:знижувати потребу в нафті через ощадливе використання матеріалів та енергії,повторне використання й переробку;розвивати іншу хімічну сировину,зокрема біосировину,і альтернативні джерела енергії. Перехід лише на інші викопні ресурси не усуває їх скінченності;варіанти оцінюють за ресурсами й наслідками. Водень є енергоносієм,для його одержання потрібне джерело енергії. Це відповідь на уявну ситуацію,не прогноз дати виснаження нафти.",
