            "answerText": "Хімічний принцип — абсорбція фенолу водним лугом:C₆H₅OH+NaOH⇄C₆H₅ONa+H₂O. Утворення розчинного феноляту сприяє утриманню фенолу в рідкій фазі;N₂ іO₂ у цих умовах не нейтралізуються. Водяна пара може обмінюватися з рідиною або конденсуватися, тому твердженняTXT«проходить без змін» не обов’язкове. Це схема принципу очищення;вона не гарантує повного вилучення без розрахунку контакту фаз,концентрації та регенерації/обробки розчину.",
